package com.example.lms.service;
import com.example.lms.dto.*; import com.example.lms.entity.*; import com.example.lms.exception.*; import com.example.lms.repository.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Service public class LibrarianService { private final LibrarianProfileRepository librarians; private final AccountRepository accounts; private final PasswordEncoder passwords; public LibrarianService(LibrarianProfileRepository l,AccountRepository a,PasswordEncoder p){librarians=l;accounts=a;passwords=p;}
 @Transactional(readOnly=true) public List<LibrarianResponse> list(){return librarians.findAll().stream().map(this::response).toList();} @Transactional(readOnly=true) public LibrarianResponse get(Long id){return response(librarian(id));}
 @Transactional public LibrarianResponse create(LibrarianRequest r){if(accounts.existsByUsername(r.username()))throw new ConflictException("Username is already in use.");var a=new Account();a.setUsername(r.username().trim());a.setPasswordHash(passwords.encode(r.password()));a.setRole(Role.LIBRARIAN);var p=new LibrarianProfile();p.setAccount(accounts.save(a));apply(p,r);return response(librarians.save(p));}
 @Transactional public LibrarianResponse update(Long id,LibrarianUpdateRequest r){var p=librarian(id);if(!p.getAccount().getUsername().equals(r.username())&&accounts.existsByUsername(r.username()))throw new ConflictException("Username is already in use.");p.getAccount().setUsername(r.username().trim());apply(p,r);return response(librarians.save(p));}
 @Transactional public void delete(Long id){librarians.delete(librarian(id));} private LibrarianProfile librarian(Long id){return librarians.findById(id).orElseThrow(()->new ResourceNotFoundException("Librarian %d was not found.".formatted(id)));} private void apply(LibrarianProfile p,LibrarianRequest r){p.setName(r.name().trim());p.setAge(r.age());p.setPhone(r.phone().trim());} private void apply(LibrarianProfile p,LibrarianUpdateRequest r){p.setName(r.name().trim());p.setAge(r.age());p.setPhone(r.phone().trim());} private LibrarianResponse response(LibrarianProfile p){var a=p.getAccount();return new LibrarianResponse(p.getId(),a.getId(),a.getUsername(),p.getName(),p.getAge(),p.getPhone(),a.getRole().name());}}
